     pub const VSTACK: u16 = 0x0002;
     pub const TEXT: u16 = 0x0003;
     pub const BUTTON: u16 = 0x0004;
     pub const IMAGE: u16 = 0x0005;
     pub const SWITCH: u16 = 0x0006;
     pub const TEXT_FIELD: u16 = 0x0007;
     pub const SPACER: u16 = 0x0008;
