    // Signal changed spacing 4 -> 12; ids stay stable.
    a.properties
        .insert(pathland_opcode::property_id::SPACING, 12.0f32.to_bits());
    let ops = emit_and_collect(&mut engine, &a);

    assert_eq!(ops.len(), 1, "only the spacing delta should emit");

